'use client'

import { cn } from '@gentleduck/libs/cn'
import type { IDirection } from '@gentleduck/primitives/direction'
import { useDirection } from '@gentleduck/primitives/direction'
import React from 'react'
import { Badge } from '../badge'
import { Button } from '../button'
import { Checkbox } from '../checkbox'
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '../command'
import { Popover, PopoverContent, PopoverTrigger } from '../popover'
import { Separator } from '../separator'
import type { IComboboxItemProps, IComboboxItemType, IComboboxProps } from './combobox.types'

const Combobox = React.forwardRef<
  HTMLButtonElement,
  IComboboxProps<readonly IComboboxItemType[], 'single' | 'multiple'>
>(
  (
    {
      value,
      defaultValue,
      items,
      command,
      commandInput,
      commandEmpty = 'Nothing found.',
      commandTriggerPlaceholder = 'Select item...',
      popover,
      popoverTrigger,
      popoverContent,
      withSearch = true,
      showSelected = true,
      children,
    },
    ref,
  ) => {
    const { dir, ...popoverProps } = popover ?? {}
    const direction = useDirection(dir as IDirection.Kind)
    const MAX_SELECTION = 2
    const resolvedValue = value ?? defaultValue

    return (
      <Popover {...popoverProps} dir={direction}>
        <PopoverTrigger asChild>
          <Button ref={ref} {...popoverTrigger} variant={popoverTrigger?.['variant'] ?? 'dashed'}>
            {popoverTrigger?.['children']}
            {showSelected &&
              (resolvedValue ? (
                resolvedValue instanceof Array && resolvedValue.length ? (
                  <>
                    <Separator orientation="vertical" />
                    <div className="flex gap-1">
                      {resolvedValue.length > MAX_SELECTION ? (
                        <Badge className="px-2 py-0.75 rounded-sm font-normal" variant={'secondary'}>
                          +{resolvedValue.length} Selected
                        </Badge>
                      ) : (
                        resolvedValue.map((item) => (
                          <Badge className="px-2 py-0.5 rounded-[3px] capitalize" key={item} variant={'secondary'}>
                            {item}
                          </Badge>
                        ))
                      )}
                    </div>
                  </>
                ) : (
                  resolvedValue
                )
              ) : (
                commandTriggerPlaceholder
              ))}
          </Button>
        </PopoverTrigger>
        <PopoverContent
          {...popoverContent}
          dir={direction}
          className={cn('w-(--gentleduck-popover-trigger-width) p-0', popoverContent?.className)}>
          <Command {...command}>
            {withSearch && <CommandInput {...commandInput} className={cn('h-8 [&_svg]:size-4.5 px-2', commandInput)} />}
            <CommandList>
              {commandEmpty && <CommandEmpty>{commandEmpty}</CommandEmpty>}
              {children(items)}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    )
  },
)
Combobox.displayName = 'Combobox'

const ComboxGroup = React.forwardRef<
  React.ComponentRef<typeof CommandGroup>,
  React.ComponentPropsWithoutRef<typeof CommandGroup>
>(({ children, ...props }, ref) => {
  return (
    <CommandGroup ref={ref} {...props}>
      {children}
    </CommandGroup>
  )
})
ComboxGroup.displayName = 'ComboxGroup'

const ComboboxItem = React.forwardRef<React.ComponentRef<typeof CommandItem>, IComboboxItemProps<IComboboxItemType>>(
  ({ item, onSelect, checked, ...props }, ref) => {
    return (
      <CommandItem
        ref={ref}
        onSelect={() => {
          onSelect?.(item.value)
        }}
        {...props}>
        <Checkbox
          aria-hidden="true"
          checked={checked}
          className="border-foreground/50 pointer-events-none"
          tabIndex={-1}
        />
        {item?.label}
      </CommandItem>
    )
  },
)
ComboboxItem.displayName = 'ComboboxItem'

export { Combobox, ComboboxItem, ComboxGroup }

import type { Button } from '../button'
import type { Checkbox } from '../checkbox'
import type { Command, CommandInput, CommandItem } from '../command'
import type { Popover, PopoverContent } from '../popover'

/** A single combobox option with a display label and underlying value. */
export interface IComboboxItemType {
  label: string
  value: string
}

/**
 * Props for the Combobox component.
 *
 * @template TData - The tuple of combobox items.
 * @template TType - Selection mode: `'single'` (default) or `'multiple'`.
 */
export interface IComboboxProps<
  TData extends readonly IComboboxItemType[],
  TType extends 'single' | 'multiple' = 'single',
> {
  /** List of items to display in the combobox. */
  items: TData
  /** Callback fired when the selected value(s) change. */
  onValueChange?: TType extends 'single'
    ? (value: TData[number]['value']) => void
    : (value: TData[number]['value'][]) => void
  /** Whether to show a search input inside the popover. */
  withSearch?: boolean
  /** Whether to display the selected value(s) in the trigger button. */
  showSelected?: boolean
  /** Initial value(s) for uncontrolled usage. */
  defaultValue?: TType extends 'single' ? TData[number]['value'] : TData[number]['value'][]
  /** Controlled value(s). */
  value?: TType extends 'single' ? TData[number]['value'] : TData[number]['value'][]
  /** Props forwarded to the Popover root. */
  popover?: React.ComponentPropsWithoutRef<typeof Popover>
  /** Props forwarded to the trigger Button. */
  popoverTrigger?: React.ComponentPropsWithoutRef<typeof Button>
  /** Props forwarded to PopoverContent. */
  popoverContent?: React.ComponentPropsWithoutRef<typeof PopoverContent>
  /** Props forwarded to the Command root. */
  command?: React.ComponentPropsWithoutRef<typeof Command>
  /** Props forwarded to CommandInput. */
  commandInput?: React.ComponentPropsWithoutRef<typeof CommandInput>
  /** Placeholder text for the search input. */
  commandTriggerPlaceholder?: string
  /** Message shown when no items match the search query. */
  commandEmpty?: string
  /** Render function for each item in the list. */
  children: (item: TData) => React.ReactNode
}

/**
 * Props for an individual combobox item (CommandItem wrapper).
 *
 * @template T - The item type extending `IComboboxItemType`.
 */
export interface IComboboxItemProps<T extends IComboboxItemType>
  extends Omit<React.ComponentPropsWithoutRef<typeof CommandItem>, 'onSelect'> {
  /** The combobox item data. */
  item: T
  /** Callback fired when this item is selected. */
  onSelect?: (value: T['value']) => void
  /** Whether the item is checked (for multiple selection). */
  checked?: React.ComponentPropsWithoutRef<typeof Checkbox>['checked']
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import type { IDirection } from '@gentleduck/primitives/direction'
import { useDirection } from '@gentleduck/primitives/direction'
import React from 'react'
import { MotionBadge } from '../badge'
import { MotionButton } from '../button'
import { MotionCheckbox } from '../checkbox'
import { Command, CommandEmpty, CommandInput, CommandList, MotionCommandItem } from '../command'
import { MotionPopover, MotionPopoverContent, PopoverTrigger } from '../popover'
import { MotionSeparator } from '../separator'
import type { IComboboxItemProps, IComboboxItemType, IComboboxProps } from './combobox.types'

const MotionCombobox = React.forwardRef<
  HTMLButtonElement,
  IComboboxProps<readonly IComboboxItemType[], 'single' | 'multiple'>
>(
  (
    {
      value,
      defaultValue,
      items,
      command,
      commandInput,
      commandEmpty = 'Nothing found.',
      commandTriggerPlaceholder = 'Select item...',
      popover,
      popoverTrigger,
      popoverContent,
      withSearch = true,
      showSelected = true,
      children,
    },
    ref,
  ) => {
    const { dir, ...popoverProps } = popover ?? {}
    const direction = useDirection(dir as IDirection.Kind)
    const MAX_SELECTION = 2
    const resolvedValue = value ?? defaultValue

    return (
      <MotionPopover {...popoverProps} dir={direction}>
        <PopoverTrigger asChild>
          <MotionButton ref={ref} {...popoverTrigger} variant={popoverTrigger?.variant ?? 'dashed'}>
            {popoverTrigger?.children}
            {showSelected &&
              (resolvedValue ? (
                Array.isArray(resolvedValue) && resolvedValue.length ? (
                  <>
                    <MotionSeparator orientation="vertical" />
                    <div className="flex gap-1">
                      {resolvedValue.length > MAX_SELECTION ? (
                        <MotionBadge className="rounded-sm px-2 py-0.75 font-normal" variant={'secondary'}>
                          +{resolvedValue.length} Selected
                        </MotionBadge>
                      ) : (
                        resolvedValue.map((item) => (
                          <MotionBadge
                            className="rounded-[3px] px-2 py-0.5 capitalize"
                            key={item}
                            variant={'secondary'}>
                            {item}
                          </MotionBadge>
                        ))
                      )}
                    </div>
                  </>
                ) : (
                  resolvedValue
                )
              ) : (
                commandTriggerPlaceholder
              ))}
          </MotionButton>
        </PopoverTrigger>
        <MotionPopoverContent
          {...popoverContent}
          dir={direction}
          className={cn('w-(--gentleduck-popover-trigger-width) p-0', popoverContent?.className)}>
          <Command {...command}>
            {withSearch && <CommandInput {...commandInput} className={cn('h-8 px-2 [&_svg]:size-4.5', commandInput)} />}
            <CommandList>
              {commandEmpty && <CommandEmpty>{commandEmpty}</CommandEmpty>}
              {children(items)}
            </CommandList>
          </Command>
        </MotionPopoverContent>
      </MotionPopover>
    )
  },
)
MotionCombobox.displayName = 'MotionCombobox'

const MotionComboboxItem = React.forwardRef<
  React.ComponentRef<typeof MotionCommandItem>,
  IComboboxItemProps<IComboboxItemType> & { index?: number }
>(({ item, onSelect, checked, index = 0, ...props }, ref) => {
  const handleSelect = React.useCallback(() => onSelect?.(item.value), [onSelect, item.value])
  return (
    <MotionCommandItem ref={ref} index={index} onSelect={handleSelect} {...props}>
      <MotionCheckbox
        aria-hidden="true"
        checked={checked}
        className="pointer-events-none border-foreground/50"
        tabIndex={-1}
      />
      {item?.label}
    </MotionCommandItem>
  )
})
MotionComboboxItem.displayName = 'MotionComboboxItem'

export { MotionCombobox, MotionComboboxItem }
